<template>
 <div class="phrase-library" :class="{'sense-library':isSense}"><div class="phrase-heading"><div><h1 class="page-title">{{ isSense?'语境义':'短语收藏' }}</h1><p class="page-sub">{{ isSense?'同一个词，不同语境各自记录释义、出处和练习':'从真题划选收藏，保留这个语境中的意思与出处' }}</p></div><button @click="$router.push('/library')">去真题划选</button></div>
 <p v-if="error" role="alert">{{ error }} <button @click="load">重新加载</button></p><p v-if="notice" role="status">{{ notice }}</p>
 <section class="card phrase-filters"><input v-model="query" :aria-label="'搜索'+label" type="search" maxlength="200" :placeholder="'搜索'+label+'、释义、上下文或出处'" /><select :value="deleted?'trash':'active'" @change="changeFolder" :aria-label="label+'收藏状态'"><option value="active">我的收藏</option><option value="trash">回收站</option></select><select v-model="tag" :aria-label="'筛选'+label+'标签'"><option value="">全部标签</option><option v-for="t in tags" :key="t">{{ t }}</option></select><span>{{ entries.length }} / {{ total }} 条</span><button v-if="isSense&&lemma" @click="lemma=''">{{ lemma }} 的语境 · 清除词形筛选</button></section>
 <div class="phrase-workspace"><aside class="card phrase-list"><button v-for="e in entries" :key="e.id" class="phrase-item" :class="{selected:selected?.id===e.id}" @click="select(e.id)"><strong>{{ e.quote }}<template v-if="isSense&&e.lemma!==e.quote.toLowerCase()"> → {{ e.lemma }}</template></strong><span>{{ e.meaning }}</span><small>{{ e.source_label }}</small><small>{{ e.tags.map(t=>'#'+t).join(' ') }}</small></button><p v-if="!entries.length">{{ deleted?'回收站没有匹配的收藏。':isSense?'没有匹配的语境义。阅读时点词或完整划选一个英文单词，再点“保存此处词义”。':'还没有匹配的短语。阅读真题时完整划选 2 至 12 个英文单词，再点“收藏短语”。' }}</p></aside>
 <section class="card phrase-detail"><template v-if="selected"><h2>{{ selected.quote }}</h2><p v-if="isSense">归一词形：{{ selected.lemma }}。每处释义独立保存，不改变词典释义或生词进度。</p><p>{{ selected.source_label }}</p><p v-if="selected.sourceStatus!=='current'" class="phrase-source-warning">{{ selected.sourceStatus==='changed'?'原文已变化，保留收藏时的上下文，不自动定位。':'来源篇章暂不可用，收藏与练习卡快照仍保留。' }}</p><blockquote class="phrase-context">{{ selected.markedContext||selected.context }}</blockquote><p v-if="selected.deleted_at">这条{{ label }}在回收站，恢复后可继续编辑和制作卡片。</p>
 <form v-else @submit.prevent="save"><label>此处释义<textarea v-model="meaning" :aria-label="'编辑'+label+'释义'" rows="3" maxlength="2000" required :disabled="busy" /></label><label>备注<textarea v-model="note" :aria-label="'编辑'+label+'备注'" rows="3" maxlength="5000" :disabled="busy" /></label><label>标签<input v-model="tagText" :aria-label="'编辑'+label+'标签'" maxlength="380" :disabled="busy" /></label><button class="primary" :disabled="busy||!dirty">保存修改</button></form>
 <div class="phrase-actions"><button :disabled="busy||!!selected.deleted_at||selected.sourceStatus!=='current'" @click="openSource">返回原文并定位</button><label>练习方式<select v-model="exerciseMode" :disabled="busy||!!selected.deleted_at" aria-label="收藏练习方式"><option value="recall">释义问答</option><option value="spelling">拼写</option><option value="cloze">原句填空</option></select></label><button :disabled="busy||!!selected.deleted_at" @click="makeCard">{{ '制作'+label+'练习卡' }}</button><button :disabled="busy" @click="changeState">{{ selected.deleted_at?'恢复收藏':'移入回收站' }}</button><button v-if="isSense" :disabled="busy" @click="filterLemma">{{ '只看 '+selected.lemma+' 的语境' }}</button></div>
 <section v-if="isSense&&selected.related?.length" class="sense-related"><h3>{{ selected.lemma }} 的其他语境</h3><p>显示最近最多 20 处，含义由你逐处填写；不自动合并。</p><button v-for="e in selected.related" :key="e.id" :disabled="busy" @click="select(e.id)">{{ e.quote }} · {{ e.meaning }}<small>{{ e.source_label }}</small></button></section>
 <p class="phrase-hint">每处收藏保留自己的上下文。{{ isSense?'同词的不同语境可以分别制卡。':'同一短语在其他出处可另行收藏；' }}已制作的练习卡不会随释义修改或移入回收站被覆盖。</p></template><p v-else>选择一条收藏查看上下文与释义。</p></section></div>
 </div>
</template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
const exerciseMode=ref('recall');
const props=defineProps({kind:{type:String,default:'phrase'}}),isSense=computed(()=>props.kind==='sense'),label=computed(()=>isSense.value?'语境义':'短语');
const route=useRoute(),router=useRouter(),entries=ref([]),tags=ref([]),total=ref(0),query=ref(''),tag=ref(''),lemma=ref(isSense.value&&typeof route.query.lemma==='string'?route.query.lemma:''),deleted=ref(false),selected=ref(null),meaning=ref(''),note=ref(''),tagText=ref(''),baseline=ref(''),busy=ref(false),error=ref(''),notice=ref('');let disposed=false,listVersion=0,detailVersion=0,timer;
const draft=()=>JSON.stringify([meaning.value,note.value,tagText.value]),dirty=computed(()=>!!selected.value&&!selected.value.deleted_at&&draft()!==baseline.value),routeId=()=>isSense.value?route.query.sense:route.query.phrase;
function canLeave(){return !busy.value&&(!dirty.value||window.confirm(label.value+'还有未保存修改，确定放弃？'));}
function setSelected(e){selected.value=e;meaning.value=e.meaning;note.value=e.note;tagText.value=e.tags.join(', ');baseline.value=draft();}
async function load(){const version=++listVersion;try{const r=await window.keeper.phraseList({query:query.value,tag:tag.value,deleted:deleted.value,kind:props.kind,...(lemma.value?{lemma:lemma.value}:{})});if(disposed||version!==listVersion)return;entries.value=r.entries;tags.value=r.tags;total.value=r.total;}catch(e){if(!disposed&&version===listVersion)error.value=e.message;}}
async function select(id,force=false){if(!force&&!canLeave())return;const version=++detailVersion;try{const e=await window.keeper.phraseGet(id);if(e.kind!==props.kind)throw Error('收藏类型不匹配，请从对应入口打开');if(!disposed&&version===detailVersion){setSelected(e);error.value='';}}catch(e){if(!disposed&&version===detailVersion)error.value=e.message;}}
async function changeFolder(event){if(!canLeave()){event.target.value=deleted.value?'trash':'active';return;}deleted.value=event.target.value==='trash';selected.value=null;++detailVersion;tag.value='';await load();}
function filterLemma(){lemma.value=selected.value.lemma;query.value='';tag.value='';}
async function save(){if(busy.value||!selected.value)return;const id=selected.value.id,payload={id,expectedRevision:selected.value.revision,meaning:meaning.value,note:note.value,tags:tagText.value.split(/[,，、\n]/).map(t=>t.trim()).filter(Boolean)};busy.value=true;error.value='';try{const r=await window.keeper.phraseEdit(payload);if(!r.ok)throw Error(r.error);if(disposed)return;notice.value='释义已保存，既有练习卡保留制作时的版本。';await select(id,true);await load();}catch(e){if(!disposed)error.value='修改未保存：'+e.message;}finally{if(!disposed)busy.value=false;}}
async function changeState(){if(!canLeave())return;const row=selected.value;if(!row.deleted_at&&!window.confirm('把这条'+label.value+'移入回收站？已经制作的练习卡和作答记录会保留。'))return;busy.value=true;error.value='';try{const r=await window.keeper.phraseState({id:row.id,expectedRevision:row.revision,action:row.deleted_at?'restore':'remove'});if(!r.ok)throw Error(r.error);if(disposed)return;notice.value=row.deleted_at?'收藏已恢复。':'已移入回收站，练习卡仍保留。';await select(row.id,true);await load();}catch(e){if(!disposed)error.value=e.message;}finally{if(!disposed)busy.value=false;}}
async function openSource(){if(busy.value)return;const id=selected.value.id,version=detailVersion;try{const a=await window.keeper.phraseAnchor(id);if(disposed||version!==detailVersion)return;await router.push({path:'/reader/'+a.examId,query:{passage:String(a.passageId),[isSense.value?'sense':'phrase']:id}});}catch(e){error.value=e.message;}}
async function makeCard(){if(busy.value)return;const prefix=isSense.value?'sense':'phrase';await router.push({path:'/cards',query:{entry:prefix+':'+selected.value.id,[prefix]:selected.value.id,...(exerciseMode.value==='recall'?{}:{exercise:exerciseMode.value})}});}
watch([query,tag,lemma],()=>{clearTimeout(timer);timer=setTimeout(load,150);});watch(routeId,id=>{if(typeof id==='string')select(id,true);});watch(()=>route.query.lemma,value=>{if(isSense.value)lemma.value=typeof value==='string'?value:'';});
onBeforeRouteLeave(()=>canLeave());onBeforeRouteUpdate(()=>canLeave());onMounted(async()=>{await load();if(typeof routeId()==='string')await select(routeId(),true);});onBeforeUnmount(()=>{disposed=true;++listVersion;++detailVersion;clearTimeout(timer);});
</script>
<style scoped>.phrase-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.phrase-filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:16px;margin:16px 0}.phrase-filters input{flex:1;min-width:160px}.phrase-library input,.phrase-library select,.phrase-library textarea{padding:9px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);box-sizing:border-box}.phrase-workspace{display:grid;grid-template-columns:minmax(230px,1fr) minmax(300px,2fr);gap:18px}.phrase-list,.phrase-detail{padding:18px;min-width:0}.phrase-item{display:flex;flex-direction:column;gap:6px;text-align:left;width:100%;padding:14px;margin-bottom:10px;overflow-wrap:anywhere}.phrase-item.selected{border-color:var(--accent);background:var(--accent-soft)}.phrase-item strong{font:18px Georgia,serif}.phrase-item small,.phrase-detail>p,.phrase-hint{font-size:12px;line-height:1.8;color:var(--muted)}.phrase-detail h2{font:24px Georgia,serif}.phrase-context{white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere;background:var(--accent-soft);padding:16px;margin:16px 0;font-family:Georgia,serif}.phrase-detail label{display:block;font-size:13px;margin:12px 0}.phrase-detail input,.phrase-detail textarea{display:block;width:100%;margin-top:5px}.phrase-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.phrase-library [role=alert]{color:var(--red)}.phrase-source-warning{color:var(--accent)!important}.sense-related{margin-top:24px;border-top:1px solid var(--border)}.sense-related p{font-size:12px;color:var(--muted)}.sense-related button{display:block;text-align:left;margin:8px 0;width:100%;overflow-wrap:anywhere}.sense-related small{display:block;color:var(--muted)}@media(max-width:900px){.phrase-workspace{grid-template-columns:1fr}}</style>
